const VECTOR_DEFS=`<defs>
<radialGradient id="vCore" cx="32%" cy="25%" r="73%"><stop stop-color="#b0b4b0"/><stop offset=".24" stop-color="#636c68"/><stop offset=".65" stop-color="#27362f"/><stop offset="1" stop-color="#0c191a"/></radialGradient>
<radialGradient id="vGold" cx="30%" cy="24%" r="78%"><stop stop-color="#ffe8a0"/><stop offset=".5" stop-color="#dfad43"/><stop offset="1" stop-color="#ad7028"/></radialGradient>
<radialGradient id="vCyto" cx="38%" cy="42%" r="65%"><stop stop-color="#f8fafb"/><stop offset="1" stop-color="#e6ecef"/></radialGradient>
<radialGradient id="vNucleus" cx="35%" cy="28%"><stop stop-color="#d4dce7"/><stop offset="1" stop-color="#a1b0c4"/></radialGradient>
<radialGradient id="vLumen"><stop stop-color="#f1f3e7"/><stop offset="1" stop-color="#bbc5ad"/></radialGradient>
<linearGradient id="vER" x2="0" y2="1"><stop stop-color="#d9c5c4"/><stop offset="1" stop-color="#bba2ad"/></linearGradient>
<linearGradient id="vRibbon"><stop stop-color="#e7c6a2"/><stop offset="1" stop-color="#a76c51"/></linearGradient>
${ASSETS.proteins}
<symbol id="proteinGlobular" viewBox="-45 -40 90 80"><path d="M-28-8C-48-25-10-42 0-26C18-43 44-19 27-3C46 20 14 38 4 23C-22 43-42 15-28-8Z" fill="url(#vRibbon)" stroke="#92634f" stroke-width="1.5"/><path d="M-26-7C-8-19 18-18 25-4S-16 18-22 6S7-3 18 13M-7-26Q-21-1 4 23" fill="none" stroke="#f7dec2" stroke-width="3"/><path d="M-31 9Q-5-8 28 5M-15-24Q12-14 17 23" fill="none" stroke="#865941" stroke-width="1.3"/></symbol>
<symbol id="proteinAntibody" viewBox="-45 -45 90 90"><g fill="#9b88b9" stroke="#655580" stroke-width="2"><rect x="-8" y="4" width="16" height="35" rx="7"/><rect x="-23" y="-31" width="14" height="43" rx="6" transform="rotate(-28 -16 -10)"/><rect x="9" y="-31" width="14" height="43" rx="6" transform="rotate(28 16 -10)"/></g><g stroke="#dacde5" stroke-width="2"><path d="M-4 12L-4 32M4 12L4 32M-26-25L-12 0M26-25L12 0"/></g></symbol>
<symbol id="hdrParticle" viewBox="-100 -100 200 200"><circle r="99" fill="url(#vCore)"/><ellipse cx="-28" cy="-44" rx="32" ry="20" fill="white" opacity=".12"/></symbol>
</defs>`;
const V={c:(x,y,r,f,st='none',sw=1)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" stroke="${st}" stroke-width="${sw}"/>`,p:(d,f='none',st='#63776b',w=1)=>`<path d="${d}" fill="${f}" stroke="${st}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`,txt:(x,y,s,size=16,anchor='middle',color='#183d45')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" style="font: ${size}px system-ui,sans-serif;fill:${color}">${s}</text>`};
function vsvg(s,w=900,h=570){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${D[current].n[lang==='fr'?0:1]}">${s}</svg>`;}
function prot(x,y,scale=1,kind=0,angle=0){return `<g transform="translate(${x} ${y}) rotate(${angle})"><use href="#${['proteinAlbumin','proteinApoE','proteinIgG','proteinApoAI','proteinPF4','proteinFibrinogen'][kind%6]}" x="${-250*scale}" y="${-250*scale}" width="${500*scale}" height="${500*scale}"/></g>`;}
function np(x,y,r=25,coated=true){let s=V.c(x,y,r,'url(#vCore)','#1a3439',.8);if(coated)for(let i=0;i<18;i++){let a=i*Math.PI/9,dx=Math.cos(a),dy=Math.sin(a);s+=V.p(`M${x+dx*r} ${y+dy*r}q${dx*8-dy*4} ${dy*8+dx*4} ${dx*12} ${dy*12}t${dx*8} ${dy*8}`,'none','#589097',1.3);}return s;}
function receptor(x,y,a=0,scale=1){return `<g transform="translate(${x} ${y}) rotate(${a}) scale(${scale})">${V.p('M-4 15L-4-3Q-21-3-20-18L-13-20Q-13-10 0-12Q13-10 13-20L20-18Q21-3 4-3L4 15Z','#8b819f','#5e5670',1)}${V.c(0,-8,3,'#cfc6dc')}</g>`;}
function leaflets(points,color='#929a70',spacing=1){let s='';for(let i=1;i<points.length-1;i+=spacing){let[x,y]=points[i],dx=points[i+1][0]-points[i-1][0],dy=points[i+1][1]-points[i-1][1],l=Math.hypot(dx,dy)||1,nx=-dy/l,ny=dx/l;for(const sign of [-1,1]){s+=V.c(x+sign*nx*5,y+sign*ny*5,2.25,color);s+=V.p(`M${x+sign*nx*3} ${y+sign*ny*3}L${x+dx/l*1.4} ${y+dy/l*1.4}M${x+sign*nx*3} ${y+sign*ny*3}L${x-dx/l*1.4} ${y-dy/l*1.4}`,'none','#b8b393',.75);}}return s;}
function bez(p0,p1,p2,p3,n=30){return Array.from({length:n},(_,i)=>{let t=i/n,q=1-t;return[q*q*q*p0[0]+3*q*q*t*p1[0]+3*q*t*t*p2[0]+t*t*t*p3[0],q*q*q*p0[1]+3*q*q*t*p1[1]+3*q*t*t*p2[1]+t*t*t*p3[1]]});}
function mitochondrion(x,y,a=0,k=1){return `<g transform="translate(${x} ${y}) rotate(${a}) scale(${k})">${V.p('M-48-12C-25-37 36-25 46-1C57 28 7 30-21 22C-48 17-62 4-48-12Z','#c8b8aa','#98745e',2)}${V.p('M-43-6C-22-22 30-18 37-1C45 17 4 22-19 14C-41 9-48 2-43-6Z','#e4d9cc','#a27c65',1.4)}${V.p('M-32-10Q-21 4-32 7M-15-17Q3 3-17 16M4-17Q18 3 3 18M25-10Q34 0 22 13','none','#a27862',2.3)}</g>`;}
function vesicle(x,y,r,type=0,opacity=1){let s=`<g opacity="${opacity}">`+V.c(x,y,r,'url(#vLumen)','#6d795b',2)+V.c(x,y,r-5,'none','#a9af7e',1.3);const pts=Array.from({length:Math.ceil(r)},(_,i)=>[x+(r-2)*Math.cos(i/r*Math.PI*2),y+(r-2)*Math.sin(i/r*Math.PI*2)]);s+=leaflets(pts,'#8e966a',2);if(type===0)s+=V.p(`M${x-r+8} ${y-8}q-25-17-23-31q4-7 11 0l19 18`,'url(#vLumen)','#7c8567',2);if(type===1)for(let i=0;i<8;i++){let a=i*2.4;s+=V.c(x+Math.cos(a)*r*.52,y+Math.sin(a)*r*.52,5+i%3,'#e7e6c1','#929d74',1);}if(type===2)for(let i=0;i<25;i++){let a=i*2.4,rr=Math.sqrt((i+.5)/25)*r*.74;s+=V.c(x+Math.cos(a)*rr,y+Math.sin(a)*rr,1.4,'#a8a375');}return s+'</g>';}
function ferritin(x,y,r=18,iron=0){let s=V.c(x,y,r,'#f0e6e7','#a28b9b',1);for(let i=0;i<24;i++){let a=i*Math.PI/12;s+=V.c(x+(r-3)*Math.cos(a),y+(r-3)*Math.sin(a),2.6,i%2?'#a38da8':'#c4b1c6');}s+=V.c(x,y,Math.max(1,iron*r*.55),'#b56d3e');return s;}
function coronaScene(t){let s=V.txt(150,42,T('Identité de synthèse','Synthetic identity'),20)+V.txt(465,42,T('Couronne biomoléculaire','Biomolecular corona'),20)+V.txt(766,42,T('Interface cellulaire','Cell interface'),20);s+=np(140,260,58,true)+V.txt(140,390,T('Cœur et revêtement','Core and coating'),16);let center=460+Math.max(0,t-.75)/.25*160;
// A curved membrane section, with the extracellular side to its left.
let boundary=[];for(let i=0;i<=75;i++){let y=80+i*5.5,x=760+12*Math.sin(y/65)+Math.max(0,t-.8)*180*Math.exp(-(((y-270)/65)**2));boundary.push([x,y]);}
let bp='M'+boundary.map(p=>p.join(' ')).join('L');s+=V.p(bp+'L900 500L900 80Z','#eee4e9','none')+V.p(bp,'none','#b8a1ae',12)+V.p(bp,'none','#ece2d4',7)+leaflets(boundary,'#a699a8');for(let i of [9,28,48,66]){const[x,y]=boundary[i];s+=receptor(x,y,-90,.85);}
s+=V.p('M855 170C813 170 808 233 831 253C852 269 895 245 900 216L900 157Z','url(#vNucleus)','#b09bbf',2)+V.p('M840 190q25-21 45-3m-55 27q25 18 48-8','none','#cdb9d5',3);
s+=np(center,260,58,true);for(let i=0;i<16;i++){let a=i*Math.PI/8+.13,approach=Math.min(1,t*3),rr=82+(1-approach)*(65+25*Math.sin(i*2));if(t>.5&&i%5===0)rr+=Math.max(0,Math.sin((t-.5)*Math.PI*5+i))*55;s+=prot(center+Math.cos(a)*rr,260+Math.sin(a)*rr,.31,i%5,a*180/Math.PI+90);}
for(let i=0;i<8;i++){let x=280+25*Math.sin(i*2.9+t*4),y=120+i*40;s+=prot(x,y,.32,i%5,i*31+t*15);}
if(values.medium==='plasma')s+=prot(center-15,339,.31,5,0);s+=V.p('M226 260L256 260M246 254L256 260L246 266','none','#899ba0',2)+V.txt(300,480,T('Biomolécules du milieu','Biomolecules in the medium'),15)+V.txt(505,425,T('Adsorption et échanges','Adsorption and exchange'),16)+V.txt(783,533,T('Membrane plasmique','Plasma membrane'),15);
s+=V.txt(450,520,T('Formes PDB : albumine · ApoE · IgG · ApoA-I · PF4','PDB shapes: albumin · ApoE · IgG · ApoA-I · PF4'),15)+V.txt(450,565,T('Exemples de formes moléculaires ; composition et proportions non mesurées.','Illustrative molecular shapes; composition and proportions are not measured.'),13);return vsvg(s,900,590);}

function water(x,y,k=.8,a=0){return `<g transform="translate(${x} ${y}) rotate(${a}) scale(${k})">${V.p('M0 0L-11 8M0 0L11 8','none','#809aa7',3)}${V.c(0,0,7,'#b94f42','#87392e',.7)}${V.c(-11,8,4.5,'#dceaf0','#91aab7',.7)}${V.c(11,8,4.5,'#dceaf0','#91aab7',.7)}</g>`;}
function cube(x,y,r=50){return V.p(`M${x-r} ${y-r*.6}L${x+r*.35} ${y-r*.6}L${x+r*.75} ${y-r}L${x-r*.6} ${y-r}Z`,'#b8dc85','#68964d',1)+V.p(`M${x+r*.35} ${y-r*.6}L${x+r*.75} ${y-r}L${x+r*.75} ${y+r*.35}L${x+r*.35} ${y+r*.75}Z`,'#91c561','#68964d',1)+V.p(`M${x-r} ${y-r*.6}L${x+r*.35} ${y-r*.6}L${x+r*.35} ${y+r*.75}L${x-r} ${y+r*.75}Z`,'#d1e8b5','#68964d',1).replace('<path ', '<path fill-opacity=".35" ');}
function field(x,y,r=25){let s='';for(let d of [25,40,55])s+=V.p(`M${x} ${y-r}C${x-d} ${y-r-50} ${x-d} ${y+r+50} ${x} ${y+r}C${x+d} ${y+r+50} ${x+d} ${y-r-50} ${x} ${y-r}`,'none','#718988',1);return s;}
function relaxivityScene(t){let s=V.txt(40,28,'A',20)+V.txt(211,35,T('Relaxivité longitudinale r₁','Longitudinal relaxivity r₁'),19)+V.txt(548,35,T('Relaxivité transverse r₂','Transverse relaxivity r₂'),19)+V.txt(211,65,T('Échanges et fluctuations','Exchange and fluctuations'),14)+V.txt(548,65,T('Variations locales de champ','Local field variations'),14);
s+=np(210,151,19,false)+field(535,151,19)+np(535,151,19,false);for(let i=0;i<4;i++){let a=i*Math.PI/2+t*3;s+=water(210+60*Math.cos(a),151+40*Math.sin(a),.7,a*180/Math.PI);s+=water(535+65*Math.cos(a+t),151+42*Math.sin(a+t),.7,a*180/Math.PI);}
s+=V.p('M748 87L875 87L875 220L748 220Z','#fafcf9','#a9b9ab',1)+cube(773,114,13)+V.txt(799,119,T('Volume exploré','Probed volume'),12,'start')+water(770,155,.5)+V.txt(799,160,T('Eau','Water'),12,'start')+np(770,193,9,false)+V.txt(799,198,'IONP',12,'start');
s+=V.txt(40,275,'B',20)+V.txt(425,275,T('Régimes de relaxivité transverse','Transverse relaxivity regimes'),20)+V.txt(220,315,T('Moyennage dynamique','Motional averaging'),17)+V.txt(570,315,T('Déphasage statique','Static dephasing'),17);
s+=field(220,411,19)+np(220,411,20,false)+cube(220,411,62);let paths=[];for(let i=0;i<35;i++){let a=i*2.4;paths.push([190+27*Math.sin(a),415+29*Math.cos(a*1.3)]);}s+=V.p('M'+paths.map(p=>p.join(' ')).join('L'),'none','#4888b8',1.5);let pt=paths[Math.floor(t*34)];s+=water(pt[0],pt[1],.4,t*130);
for(let i=0;i<7;i++){let a=i*2.4,rad=i?35:0,x=555+Math.cos(a)*rad,y=425+Math.sin(a)*rad;s+=field(x,y,10)+np(x,y,13,false);}s+=cube(581,379,33);s+=V.p('M565 365l17 9-9 12 18 3-5-20-17 8 12 14','none','#4888b8',1.5)+water(575+10*Math.sin(t*20),379+12*Math.cos(t*21),.4,t*180);
s+=V.p('M104 523L743 523M735 518L743 523L735 528','none','#84928c',1.6)+V.txt(423,552,T('Taille et aimantation modifient le régime ; r₂ ne croît pas indéfiniment.','Size and magnetization change the regime; r₂ does not grow indefinitely.'),14);return vsvg(s,900,580);}
function coatingScene(t){let s=V.txt(450,38,T('Trois fonctions de surface à distinguer','Three distinct surface functions'),21);let parts=[[145,'#dfb576',T('Ancrage','Anchoring'),T('Liaison au cœur','Binding to the core')],[450,'#a6c2ad',T('Chaîne hydrophile','Hydrophilic chain'),T('Dispersion et stabilité','Dispersion and stability')],[755,'#92b6ca',T('Fonction ajoutée','Added function'),T('Reconnaissance ou charge utile','Recognition or payload')]];for(let[x,c,a,b]of parts){s+=V.p(`M${x-130} 91h95q-12-34 22-34t22 34h95v115h-95q12 34-22 34t-22-34h-95Z`,c,'#66888d',1)+V.txt(x,134,a,19)+V.txt(x,172,b,15);}
s+=np(353,385,80,false);s+=V.p('M353 385L353 305A80 80 0 0 1 433 385Z','#c79e50','#9b7a3f',1)+V.p('M353 385L353 290A95 95 0 0 1 448 385L433 385A80 80 0 0 0 353 305Z','#a3c1a3','#71966f',1);for(let i=0;i<22;i++){let a=i*2*Math.PI/22,r=95;let x=353+Math.cos(a)*r,y=385+Math.sin(a)*r;s+=V.p(`M${353+Math.cos(a)*80} ${385+Math.sin(a)*80}Q${x-5} ${y+8} ${x} ${y}t${Math.cos(a)*15} ${Math.sin(a)*15}`,'none','#7b9d9c',2);if(i%4===0)s+=prot(353+Math.cos(a)*119,385+Math.sin(a)*119,.2,2,a*180/Math.PI);}
s+=V.p('M401 323L550 293M447 362L550 356M459 428L550 429','none','#86958c',1)+V.txt(560,298,T('Agent d’ancrage','Anchoring group'),17,'start')+V.txt(560,361,T('Couche hydrophile','Hydrophilic layer'),17,'start')+V.txt(560,434,T('Ligand / composé associé','Ligand / associated compound'),17,'start')+V.txt(450,545,T('La fonctionnalisation ne prouve ni ciblage effectif ni libération.','Functionalization alone proves neither targeting nor release.'),14);return vsvg(s,900,570);}
function photoScene(t){let s=V.txt(450,40,T('Absorption optique → dissipation thermique','Optical absorption → heat dissipation'),22);for(let j=0;j<3;j++){let pts=[];for(let i=0;i<60;i++){let x=55+i*4;pts.push([x,220+j*24+9*Math.sin(i*.4-t*18)]);}s+=V.p('M'+pts.map(p=>p.join(' ')).join('L'),'none','#bf4a48',2);}
s+=np(450,255,66,false);for(let i=0;i<4;i++){let r=75+((t*80+i*25)%95);s+=V.c(450,255,r,'none','#d6804f',1.5);}s+=V.p('M330 243L366 243M359 237L366 243L359 249','none','#bc5448',2)+V.txt(175,155,T('Lumière absorbée','Absorbed light'),18)+V.txt(450,440,T('Voies non radiatives','Nonradiative pathways'),18)+V.txt(713,256,T('Chaleur vers le milieu','Heat to the medium'),17)+V.p('M620 275L750 275M741 270L750 275L741 280','none','#cf8e5a',2);
s+=V.txt(450,492,T('Le mécanisme d’absorption dépend du matériau et de la longueur d’onde.','Absorption depends on material and wavelength.'),15)+V.txt(450,525,T('Ce schéma n’attribue pas une résonance plasmonique de l’or aux IONPs.','This diagram does not attribute gold plasmon resonance to IONPs.'),14);return vsvg(s,900,560);}
function vectorScene(id,t){if(id==='corona')return coronaScene(t);if(id==='fate')return fateScene(t);if(id==='relaxivity')return relaxivityScene(t);if(id==='delivery')return coatingScene(t);if(id==='photo')return photoScene(t);if(id==='assembly'){let raw=ASSETS['cij-'+lang];raw=raw.replace(/<\?xml[^>]*>/,'');return raw;}return null;}
function proteinEvidence(){const rows=[['Albumine','Albumin','1AO6',T('Chaîne A ; forme globulaire de référence.','Chain A; reference globular form.')],['ApoE','ApoE','2L7B',T('ApoE3, modèle RMN 1 ; variant monomérique à cinq substitutions.','ApoE3, NMR model 1; monomeric variant with five substitutions.')],['Immunoglobuline G','Immunoglobulin G','1HZH',T('IgG humaine b12 intacte : exemple d’architecture, pas identification de cet anticorps dans la couronne.','Intact human b12 IgG: architectural example, not identification of this antibody in the corona.')],['ApoA-I','ApoA-I','8VXJ',T('Chaîne C (notation auteur), domaine résolu ; extrémité C-terminale absente, Fab exclu.','Author chain C, resolved domain; C-terminal region absent, Fab excluded.')],['PF4','PF4','1RHP',T('Assemblage tétramérique A–D.','Tetrameric assembly A–D.')],['Fibrinogène','Fibrinogen','3GHG',T('Chaînes A–F ; régions non résolues non inventées. Réservé à la vue plasma.','Chains A–F; unresolved regions not invented. Plasma view only.')]];return `<details><summary>${T('Pourquoi ces protéines ? Structures et références','Why these proteins? Structures and references')}</summary><p>${T('La sélection s’appuie sur les tableaux 2–4 de Mekseriwattana et al. (2023) pour les SPIONs nus, citratés et à ligand riboflavine–citrate exposés à du sérum humain, puis sur Vogt et al. (2015) pour le contexte plasma. Ce panel n’est ni une composition mesurée de nos formulations, ni un classement universel. Les identifications de chaînes d’immunoglobulines ne prouvent pas la présence d’un anticorps particulier.','Selection draws on Tables 2–4 of Mekseriwattana et al. (2023) for bare, citrate-coated and riboflavin–citrate SPIONs exposed to human serum, and Vogt et al. (2015) for plasma. This panel is neither a measured composition of our formulations nor a universal ranking. Immunoglobulin-chain identifications do not establish the presence of a particular antibody.')}</p><div class="protein-atlas">${rows.map((r,i)=>`<div><svg viewBox="-250 -150 500 300" role="img" aria-label="${r[lang==='fr'?0:1]}"><use href="#${['proteinAlbumin','proteinApoE','proteinIgG','proteinApoAI','proteinPF4','proteinFibrinogen'][i]}" x="-250" y="-250" width="500" height="500"/></svg><b>${r[lang==='fr'?0:1]}</b> · <a href="https://www.rcsb.org/structure/${r[2]}" target="_blank" rel="noopener noreferrer">PDB ${r[2]}</a><p>${r[3]}</p></div>`).join('')}</div><p>${T('Projections des coordonnées Cα, à la même échelle entre protéines dans cette galerie. Ce ne sont pas des surfaces atomistiques ni des conformations adsorbées. Les chaînes, modèles et dimensions projetées sont documentés dans l’archive.','Cα-coordinate projections, at the same scale between proteins in this gallery. These are not atomistic surfaces or adsorbed conformations. Chains, models and projected dimensions are documented in the archive.')}</p></details>`;}

const vectorBank=document.createElementNS("http://www.w3.org/2000/svg","svg");vectorBank.setAttribute("width","0");vectorBank.setAttribute("height","0");vectorBank.setAttribute("aria-hidden","true");vectorBank.style.position="absolute";vectorBank.innerHTML=VECTOR_DEFS;document.body.appendChild(vectorBank);

// V4.8: scientific figure conventions; time is illustrative unless a curve has physical units.
function panel(x,y,w,h,title){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="#fff" stroke="#d4dde2"/><text x="${x+16}" y="${y+25}" style="font:600 16px Arial;fill:#273f4b">${title}</text>`;}
function np(x,y,r=25,coated=true){let s=`<g><circle cx="${x}" cy="${y}" r="${r}" fill="url(#vCore)" stroke="#243944" stroke-width="1"/>`;for(let j=0;j<6;j++){let a=j*Math.PI/3;s+=V.p(`M${x} ${y}L${x+r*.92*Math.cos(a)} ${y+r*.92*Math.sin(a)}`,'none','#c2cccc',.45);}if(coated)for(let i=0;i<24;i++){let a=i*Math.PI/12,dx=Math.cos(a),dy=Math.sin(a),q=r*.16;s+=V.p(`M${x+dx*r} ${y+dy*r}q${dx*q-dy*q*.5} ${dy*q+dx*q*.5} ${dx*q*1.5} ${dy*q*1.5}t${dx*q} ${dy*q}`,'none','#688a96',1.1);}return s+'</g>';}

function coatingScene(t){let s=panel(20,20,405,430,T('A · Surface fonctionnalisée','A · Functionalized surface'))+panel(445,20,435,430,T('B · Fonctions distinctes','B · Distinct functions'));s+=np(215,230,83,false);
for(let i=0;i<32;i++){let a=i*2*Math.PI/32,q=.06*Math.sin(t*8+i),dx=Math.cos(a),dy=Math.sin(a);let sx=215+84*dx,sy=230+84*dy,ex=215+128*Math.cos(a+q),ey=230+128*Math.sin(a+q);s+=V.c(sx,sy,3,'#a66b49')+V.p(`M${sx} ${sy}Q${215+105*Math.cos(a-.06)} ${230+105*Math.sin(a-.06)} ${ex} ${ey}`,'none','#5d8193',1.8);if(i%8===0)s+=prot(ex,ey,.13,2,a*180/Math.PI);}
const labels=[[125,'#a66b49',T('Ancrage au cœur','Core anchoring')],[225,'#5d8193',T('Couche hydrophile','Hydrophilic layer')],[325,'#775b8c',T('Ligand / composé associé','Ligand / associated compound')]];labels.forEach(([y,c,label],i)=>{s+=V.c(480,y,7,c)+V.txt(505,y+6,label,18,'start');if(i===Math.min(2,Math.floor(t*3)))s+=V.p(`M468 ${y+20}H845`,'none',c,2);});s+=V.txt(215,404,T('Fluctuations de chaînes illustratives','Illustrative chain fluctuations'),14)+V.txt(450,485,T('La fonctionnalisation seule ne démontre ni ciblage ni libération.','Functionalization alone demonstrates neither targeting nor release.'),15);return vsvg(s,900,510);}
function dipoleScene(t){const r=values.distance,a=values.angle*Math.PI/180,sep=55*r,x1=450-sep/2,x2=450+sep/2,y=205;let s=panel(20,20,860,380,T('Interaction de deux moments magnétiques','Interaction of two magnetic moments'));s+=np(x1,y,30,false)+np(x2,y,30,false)+arrow(x1,y,Math.PI/2,40,'#edf5f8',3)+arrow(x2,y,Math.PI/2+a,40,'#edf5f8',3);
// Progressive construction of the dipole field; it does not rotate the selected moments.
for(let j=0;j<8;j++){let d=36+j*12;let opacity=Math.min(1,Math.max(0,t*3-j*.12));s+=`<g opacity="${opacity}">`+V.p(`M${x1+30} ${y}C${x1+d*2} ${y-d*2} ${x1-d*2} ${y-d*2} ${x1-30} ${y}M${x1+30} ${y}C${x1+d*2} ${y+d*2} ${x1-d*2} ${y+d*2} ${x1-30} ${y}`,'none','#7e9eae',1)+'</g>';}
s+=line(x1,340,x2,340,'#344c5b',1,'5 4')+V.txt(450,370,'r / d = '+r.toFixed(1)+' · θ = '+values.angle+'°',17)+V.txt(450,437,T('Construction des lignes de champ ; géométrie fixée par les curseurs.','Field-line construction; geometry is set by the sliders.'),15);$('math').innerHTML='Udd = μ₀/(4πr³) [m₁·m₂ − 3(m₁·r̂)(m₂·r̂)]<br>'+T('Énergie réduite : ','Reduced energy: ')+(-2*Math.cos(a)/r**3).toFixed(3);return vsvg(s,900,465);}
function assemblyScene(t){let raw=ASSETS['cij-'+lang].replace(/<\?xml[^>]*>/,'');let s=raw.replace('<svg ','<svg x="15" y="15" width="870" height="455" ');const labels=[T('Flux organique','Organic stream'),T('Flux aqueux','Aqueous stream'),T('Mélange','Mixing'),T('Assemblages','Assemblies')];for(let i=0;i<4;i++){let x=40+i*220;s+=`<rect x="${x}" y="490" width="200" height="62" rx="4" fill="${Math.floor(t*4)===i?'#e9f1f5':'#fff'}" stroke="#aebfc8"/>`+V.txt(x+100,514,labels[i],15);let len=180*Math.min(1,Math.max(0,t*4-i));s+=V.p(`M${x+10} 537h${len}`,'none',i<2?'#a66b49':'#315b78',4);}
// Preserve the supplied apparatus drawing; moving markers below explicitly show process order, not simulated flow.
s+=V.txt(450,580,T('Séquence du procédé ; le dessin du montage est conservé. Pas de simulation hydrodynamique.','Process sequence; apparatus drawing preserved. Not a hydrodynamic simulation.'),13);return vsvg(s,900,605);}
function vectorScene(id,t){if(id==='macrospin')return macroScene(t);if(id==='interactions')return dipoleScene(t);if(id==='corona')return coronaScene(t);if(id==='fate')return fateScene(t);if(id==='relaxivity')return relaxivityScene(t);if(id==='delivery')return coatingScene(t);if(id==='photo')return photoScene(t);if(id==='assembly')return assemblyScene(t);return null;}

function mpiScene(t){const pos=180+540*t;let s=panel(20,20,860,390,T('Champ de sélection et réponse locale','Selection field and local response'));for(let i=0;i<17;i++)for(let j=0;j<7;j++){let x=70+i*48,y=90+j*40,bx=(x-pos)/120,by=-(y-210)/120,b=Math.hypot(bx,by),a=Math.atan2(bx,-by),len=16*Math.tanh(b);s+=arrow(x,y,a,len,'#a3b5c0',1.1);}
s+=V.c(pos,210,38,'#a66b491a','#a66b49',1.5)+line(pos,70,pos,360,'#a66b49',1,'5 5');for(let i=0;i<11;i++){let x=160+i*50,b=(x-pos)/60;s+=np(x,210,10,false)+arrow(x,210,b<0?-Math.PI/2:Math.PI/2,20*Math.abs(Math.tanh(b)),'#315b78',2);}
s+=V.txt(450,390,T('La région de champ faible traverse les traceurs.','The low-field region crosses the tracers.'),16)+V.txt(450,440,T('Les moments proches de cette région répondent le plus à une variation du champ.','Moments near this region respond most strongly to a field change.'),15)+V.txt(450,472,T('Coupe 2D illustrative ; ni géométrie de scanner ni image reconstruite.','Illustrative 2D section; neither scanner geometry nor a reconstructed image.'),13);return vsvg(s,900,500);}
// One visual policy for all modules, while retaining the established source geometries.
const establishedVectorScene=vectorScene;
function refinedScene(id,t){if(id==='mpi')return mpiScene(t);return establishedVectorScene(id,t);}

// V4.9: introduce internal moments before the single-particle approximation.
function macroScene(t){const stage=Math.min(2,Math.floor(t*3)),a=stage===2?.3+1.1*Math.sin((t-2/3)*Math.PI*3):.3;let s='';
s+=panel(24,20,852,435,T('Des moments atomiques au spin géant','From atomic moments to a giant spin'));
s+=V.c(285,225,132,'#edf2f5','#728c9a',2);
if(stage<2){for(let i=0;i<44;i++){const r=112*Math.sqrt((i+.5)/44),q=i*2.399;s+=`<g data-internal-spin="${i}" opacity="${Math.min(1,.4+t*2)}">`+arrow(285+r*Math.cos(q),225+r*Math.sin(q),a+(i%2?Math.PI:0),i%2?12:20,i%2?'#ad7151':'#315b78',2)+'</g>';}
s+=V.txt(285,390,T('Moments atomiques ordonnés','Ordered atomic moments'),18);
}else{s+=`<g data-macrospin="single">`+arrow(285,225,a,100,'#315b78',7)+'</g>'+V.txt(285,390,T('Un seul moment par nanoparticule','One moment per nanoparticle'),18);}
if(stage===0){s+=V.txt(625,175,T('IONP ferrimagnétique','Ferrimagnetic IONP'),23)+V.txt(625,224,T('Deux sous-réseaux opposés','Two opposing sublattices'),18)+V.txt(625,263,T('Contributions inégales','Unequal contributions'),18)+V.txt(625,318,T('Le moment total est non nul.','The total moment is nonzero.'),18);}
if(stage===1){s+=arrow(525,210,.3,90,'#315b78',5)+arrow(630,210,.3+Math.PI,55,'#ad7151',5)+arrow(755,210,.3,35,'#243944',5)+V.txt(630,315,T('Somme vectorielle des moments','Vector sum of the moments'),18)+V.txt(630,354,T('Moment résultant de la particule','Net particle moment'),18);}
if(stage===2){s+=V.txt(625,160,T('Approximation monodomaine','Single-domain approximation'),21)+V.txt(625,220,T('La direction du moment varie.','The moment direction changes.'),18)+V.txt(625,260,T('Sa norme reste constante ici.','Its magnitude stays constant here.'),18)+V.txt(625,320,T('Ce moment sera utilisé ensuite.','This moment is used from now on.'),18);}
s+=V.txt(450,493,T('Positions schématiques : ni maille cristalline ni rapport stœchiométrique.','Schematic positions: neither a crystal lattice nor a stoichiometric ratio.'),14);return vsvg(s,900,520);}
function fateGeometry(t){const clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x)};const close=ease((t-1/6)*6),travel=ease((t-1/3)*6),fusion=ease((t-.5)*6),redistribution=ease((t-2/3)*6),erosion=ease((t-5/6)*6);return {close,travel,fusion,redistribution,erosion,x:690-150*travel,y:210+82*travel,r:48+13*travel+8*fusion};}
function fateScene(t){const g=fateGeometry(t),stage=Math.min(5,Math.floor(t*6));let s=V.p('M80 130Q55 140 55 200L55 460Q55 500 110 500H815Q850 500 850 460V130Z','url(#vCyto)','none');
s+=V.txt(180,65,T('Milieu extracellulaire','Extracellular medium'),16)+V.txt(150,475,T('Cytoplasme','Cytoplasm'),16);
// A section of cell with nucleus, ER and mitochondria; the upper contour is its plasma membrane.
s+=V.p('M114 271C135 222 230 225 256 277C283 321 250 390 194 403C132 412 100 365 114 271Z','url(#vNucleus)','#9cabc0',3)+V.p('M128 277C149 238 224 238 244 282C264 325 239 377 192 389C141 397 114 361 128 277Z','none','#e0e6ef',2);
s+=V.c(181,315,24,'#879ab2')+V.txt(185,365,T('Noyau','Nucleus'),14);
for(let i=0;i<5;i++)s+=V.p(`M${280+i*6} ${248+i*27}q35-14 50 2t21 15`,'none','#b5a0aa',6)+V.p(`M${280+i*6} ${248+i*27}q35-14 50 2t21 15`,'none','#eddee3',2);
s+=mitochondrion(345,429,-18,.7)+mitochondrion(125,190,20,.55);
// Continuous invagination contour. The neck narrows before fission.
let membrane='M55 130H850';if(stage<2){const q=stage===0?Math.min(1,t*6):1,depth=80*q,neck=42*(1-g.close)+2;membrane=`M55 130H${690-neck}C${690-neck} ${145+depth*.2} ${636} ${130+depth*.7} 645 ${130+depth}C645 ${130+depth+48*q} 735 ${130+depth+48*q} 735 ${130+depth}C744 ${130+depth*.7} ${690+neck} ${145+depth*.2} ${690+neck} 130H850`;}
s+=V.p(membrane,'none','#899779',10)+V.p(membrane,'none','#e1dfc6',5);
let x=g.x,y=g.y,r=g.r;if(stage===0){y=99+111*Math.min(1,t*6);}
if(stage>=2)s+=`<g data-compartment="particle-bearing">`+vesicle(x,y,r,stage>=3?2:1)+'</g>';
if(stage===1&&g.close>.75)s+=vesicle(x,y,r,0,Math.min(1,(g.close-.75)*4));
// A lysosome approaches the same late endosome and merges with it.
if(stage===2||stage===3){const lx=705-115*g.fusion,ly=370-65*g.fusion;const opacity=1-g.fusion;s+=vesicle(lx,ly,29,2,opacity);if(stage===3&&g.fusion>.1&&g.fusion<.9)s+=V.p(`M${x+40} ${y+15}Q${lx-15} ${ly-35} ${lx} ${ly-20}L${lx-15} ${ly+15}Q${x+48} ${y+45} ${x+30} ${y+30}Z`,'url(#vLumen)','#879779',2);if(opacity>.4)s+=V.txt(lx,ly+49,T('Lysosome','Lysosome'),15);}
// Multiple cargo particles stay inside the moving, maturing compartment.
for(let i=0;i<12;i++){const a=i*2.399,rr=18*Math.sqrt((i+.5)/12),target=r-12,rad=rr*(1-g.redistribution)+target*g.redistribution,sz=4.8*(1-.55*g.erosion);s+=`<g data-cargo="${i}" data-radius="${rad}">`+np(x+rad*Math.cos(a),y+rad*Math.sin(a),sz,false)+'</g>';}
const labels=[T('Invagination','Invagination'),T('Fermeture de la vésicule','Vesicle closure'),T('Endosome précoce → tardif','Early → late endosome'),T('Fusion avec un lysosome','Fusion with a lysosome'),T('Redistribution périphérique','Peripheral redistribution'),T('Érosion des IONPs','IONP erosion')];s+=V.txt(460,35,labels[stage],23);
if(stage>=2)s+=V.txt(x,y-r-22,stage===2?T('Compartiment en maturation','Maturing compartment'):T('Compartiment endolysosomal','Endolysosomal compartment'),16);
if(stage>=4){s+=V.p(`M${x+r-4} ${y+25}L720 405`,'none','#839177',1)+V.txt(720,426,T('Membrane lysosomale','Lysosomal membrane'),15);}
if(stage===5){for(let i=0;i<3;i++)s+=ferritin(650+i*48,235-i%2*25,13,g.erosion);s+=V.txt(704,180,T('Ferritine · stockage du fer','Ferritin · iron storage'),16)+`<path d="M${x+r-5} ${y-20}Q627 244 647 240" stroke="#a66b49" fill="none" stroke-dasharray="4 4" stroke-width="1.5"/>`+V.txt(705,284,T('Transfert local proposé','Proposed local transfer'),13)+V.txt(705,306,T('Mécanisme non résolu','Unresolved mechanism'),13);}
s+=V.txt(450,540,T('Lartigue et al., ACS Nano 2013 · figures 5–7 · schéma non à l’échelle','Lartigue et al., ACS Nano 2013 · Figures 5–7 · diagram not to scale'),14);return vsvg(s,900,565);}
// V4.11 magnetic introduction: qualitative diagrams, then the explicit macrospin approximation.
function domainScene(){let s=panel(20,20,420,380,T('Plusieurs domaines','Multiple domains'))+panel(460,20,420,380,T('Un seul domaine','Single domain'));s+=V.c(230,195,110,'#edf2f5','#869caa',2)+V.c(670,195,110,'#edf2f5','#869caa',2)+V.p('M230 85V305','none','#a77751',3);for(let row=0;row<4;row++)for(let col=0;col<4;col++){let x=-64+col*42,y=-64+row*42;if(Math.hypot(x,y)>90)continue;s+=arrow(230+x,195+y,col<2?0:Math.PI,20,'#31579c',2)+arrow(670+x,195+y,0,20,'#31579c',2)}s+=V.txt(230,355,T('Paroi entre domaines','Domain wall'),18)+V.txt(670,355,T('Aucune paroi interne','No internal domain wall'),18)+V.txt(450,442,T('Un cœur monodomaine peut être bloqué ou superparamagnétique.','A single-domain core can be blocked or superparamagnetic.'),17);return vsvg(s,900,475)}
function macroScene(t){const stage=Math.min(2,Math.floor(t*3)),a=2*Math.PI*t;let s=panel(20,20,420,400,T('Ordre ferrimagnétique interne','Internal ferrimagnetic order'))+panel(460,20,420,400,T('Moment résultant','Net moment'));s+=V.c(230,210,115,'#edf2f5','#8b9eaa',2);if(stage<2){for(let i=0;i<40;i++){const r=92*Math.sqrt((i+.5)/40),q=i*2.399;s+=`<g data-internal-spin="${i}">`+arrow(230+r*Math.cos(q),210+r*Math.sin(q),a+(i%2?Math.PI:0),i%2?12:19,i%2?'#a66b49':'#31579c',2)+'</g>'}}else{s+=`<g data-macrospin="single">`+arrow(230,210,a,85,'#31579c',6)+'</g>'}s+=V.txt(230,370,stage<2?T('Rotation collective · opposition conservée','Collective rotation · antiparallel order kept'):T('Approximation du spin géant','Giant-spin approximation'),15);if(stage>=1){s+=V.c(670,210,115,'#edf2f5','#8b9eaa',2)+arrow(670,210,a,85,'#31579c',6)+V.txt(670,370,T('La somme tourne avec les moments.','The sum rotates with the moments.'),16)}else s+=V.txt(670,210,T('Puis : somme vectorielle','Next: vector sum'),21);s+=V.txt(450,461,T('Rotation imposée pour illustrer le modèle ; positions non cristallographiques.','Prescribed rotation illustrates the model; positions are not crystallographic.'),14);return vsvg(s,900,490)}
function easyHardScene(t){const a=Math.PI*t,x=205,y=210,r=85;let s=panel(20,20,390,400,T('Orientation du spin géant','Giant-spin orientation'))+panel(430,20,450,400,T('Potentiel à champ nul','Zero-field potential'));s+=V.c(x,y,r,'url(#vCore)','#7f94a0',1)+line(x,y-125,x,y+125,'#237e78',2,'6 5')+line(x-135,y,x+135,y,'#b1774b',2,'6 5')+arrow(x,y,a,67,'#f4f8fa',4)+V.txt(x,72,T('Axe facile','Easy axis'),17)+V.txt(x,372,T('Axe difficile : perpendiculaire','Hard axis: perpendicular'),16)+V.txt(x,399,'θ = '+Math.round(t*180)+'°',15);
const X=q=>478+350*q/Math.PI,Y=e=>320-190*e;let pts=Array.from({length:101},(_,i)=>{const q=i/100*Math.PI;return[X(q),Y(Math.sin(q)**2)]});s+=line(478,320,828,320,'#8397a4',1)+line(478,115,478,320,'#8397a4',1)+path(pts,'#31579c',3)+V.c(X(a),Y(Math.sin(a)**2),6,'#b1774b')+V.txt(650,95,'E / KV',17)+V.txt(478,345,'0°',15)+V.txt(653,345,'90°',15)+V.txt(828,345,'180°',15)+V.txt(653,124,T('Maximum · difficile','Maximum · hard'),16)+V.txt(653,379,T('Minima à 0° et 180° · facile','Minima at 0° and 180° · easy'),16);return vsvg(s,900,440)}
const previousRefinedScene=refinedScene;
function finalMagneticScene(id,t){if(id==='monodomain')return domainScene();if(id==='anisotropy')return easyHardScene(t);return previousRefinedScene(id,t)}
// V4.12: planar overdamped thermal dipoles, reduced time. No physical relaxation rate inferred.
const pairCache=new Map();
function pairTrajectory(gap,exchange){const key=gap+':'+exchange;if(pairCache.has(key))return pairCache.get(key);const d=12e-9,r=d+gap*1e-9,mu=480000*Math.PI/6*d**3,lambda=1e-7*mu*mu/(1.380649e-23*300*r**3),j=exchange&&gap===0?20:0;let seed=97643,a=.4,b=j? .4:2.1;const random=()=>{seed=(1664525*seed+1013904223)>>>0;return(seed+.5)/4294967296},normal=()=>Math.sqrt(-2*Math.log(random()))*Math.cos(2*Math.PI*random());const trace=[];for(let n=0;n<=1600;n++){trace.push({a,b});for(let k=0;k<12;k++){const delta=a-b,g1=lambda*(-Math.sin(delta)+3*Math.sin(a)*Math.cos(b))+j*Math.sin(delta),g2=lambda*(Math.sin(delta)+3*Math.cos(a)*Math.sin(b))-j*Math.sin(delta),dt=.0015;a+=-g1*dt+Math.sqrt(2*dt)*normal();b+=-g2*dt+Math.sqrt(2*dt)*normal();}}const out={trace,lambda,j};pairCache.set(key,out);return out}
function dipoleScene(t){const gap=values.gap??35,exchange=!!values.exchange&&gap===0,model=pairTrajectory(gap,exchange),p=model.trace[Math.min(1600,Math.floor(t*1600))],sep=96+8*gap,x1=450-sep/2,x2=450+sep/2,y=205;let s=panel(20,20,860,470,T('Deux moments thermiquement fluctuants','Two thermally fluctuating moments'));for(const[x,a]of [[x1,p.a],[x2,p.b]])s+=V.c(x,y,48,'url(#vCore)','#8096a5',1)+arrow(x,y,a+Math.PI/2,37,'#f2f7fb',4);
if(exchange)s+=V.p('M450 174V236','none','#b1774b',7)+V.txt(450,122,T('Interface d’échange imposée','Imposed exchange interface'),16);else s+=V.txt(450,95,T('Couplage dipolaire seul','Dipolar coupling only'),18);
s+=line(x1,305,x2,305,'#657e8e',1,'5 4')+line(x1,295,x1,315,'#657e8e',1)+line(x2,295,x2,315,'#657e8e',1)+V.txt(450,340,T('Centre–centre : ','Centre-to-centre: ')+(12+gap).toFixed(0)+' nm',17)+V.txt(450,372,T('Entre surfaces : ','Surface gap: ')+gap+' nm',17)+V.txt(450,411,'λ = U₀ / kBT = '+model.lambda.toFixed(3)+(exchange?' · J / kBT = 20':''),17)+V.txt(450,448,T('300 K · diamètre 12 nm · temps réduit, sans calibration en secondes','300 K · diameter 12 nm · reduced time, no calibration in seconds'),14);
s+=V.txt(450,530,T('Le voisin modifie l’énergie d’orientation ; les trajectoires répondent à ce couplage.','The neighbour changes orientation energy; trajectories respond to this coupling.'),14);return vsvg(s,900,555)}
function coronaScene(t){const cx=135+565*t,cy=250;let s=V.p('M35 95H785V410H35Z','#fff6f4','none')+V.p('M35 95H785M35 410H785','none','#dab0ae',3);s+=V.txt(450,40,T('Dans le plasma : adsorption, échanges, rencontre cellulaire','In plasma: adsorption, exchange, cell encounter'),22);
// Background red blood cells provide context; all objects are deliberately out of scale.
for(let i=0;i<4;i++){const x=60+((i*217+170*t)%670),y=i%2?365:140;s+=`<g opacity=".3" transform="translate(${x} ${y}) rotate(${i*33})"><ellipse rx="42" ry="20" fill="#b95561"/><ellipse rx="25" ry="10" fill="#f8c8c5"/></g>`;}
let membrane=Array.from({length:61},(_,i)=>[790+8*Math.sin(i/9),85+i*5.7]);let path='M'+membrane.map(p=>p.join(' ')).join('L');s+=V.p(path+'L900 450V80Z','url(#vCyto)','none')+V.p(path,'none','#a3ad93',9)+V.p(path,'none','#e8e5d4',4)+leaflets(membrane,'#909d87',2)+V.txt(845,485,T('Cellule','Cell'),17);for(const i of[8,25,44])s+=receptor(membrane[i][0],membrane[i][1],-90,.7);s+=V.p('M875 175C820 180 823 310 890 315L900 175Z','url(#vNucleus)','#9eafbd',2);
for(let i=0;i<15;i++){const x=60+((i*113+220*t)%660),y=185+(i%3)*66;s+=prot(x,y,.10,i%5,i*31+t*100);}
s+=np(cx,cy,43,true);const count=Math.min(14,Math.floor(Math.max(0,t-.035)*56)),vroman=values.coronaMode==='vroman';for(let i=0;i<count;i++){const a=i*Math.PI*2/14,replace=vroman&&t>.43+(i%7)*.045,kind=replace?(i%3+1):(vroman?0:i%5),exchange=i%4===0&&t>.36;const pulse=exchange?Math.sin(t*42+i):0,rr=66+Math.max(0,pulse)*24;s+=prot(cx+rr*Math.cos(a),cy+rr*Math.sin(a),.12,kind,a*180/Math.PI);if(replace&&t<.78&&i%3===0){const dist=95+((t*4+i*.17)%1)*45;s+=`<g opacity=".65">`+prot(cx-dist*.7,cy+Math.sin(a)*dist,.09,0,a*180/Math.PI)+'</g>';}}
if(t<.17)s+=V.txt(cx,cy+112,T('Surface initiale','Initial surface'),16);else s+=V.txt(cx,cy+119,T('Couronne en renouvellement','Exchanging corona'),16);
s+=V.p('M70 455H280l-10-5m10 5l-10 5','none','#a87370',1.5)+V.txt(170,485,T('Transport dans le sang','Blood transport'),15)+V.txt(450,535,vroman?T('Scénario Vroman : remplacement compétitif possible, non universel.','Vroman scenario: possible competitive replacement, not universal.'):T('Adsorption et désorption : plusieurs temps de résidence.','Adsorption and desorption: different residence times.'),16)+V.txt(450,565,T('Formes PDB ; abondances et affinités illustratives, sans classement des protéines réelles.','PDB shapes; illustrative abundance and affinity, no ranking of actual proteins.'),13)+V.txt(450,590,T('Temps et dimensions non à l’échelle. La rencontre précède l’activité d’endocytose.','Time and size are not to scale. Cell encounter precedes the endocytosis activity.'),13);return vsvg(s,900,615)}
function mriVectorState(u,t1,t2){if(u<.2){const a=Math.PI/2*u/.2;return{z:Math.cos(a),xy:Math.sin(a),time:0,pulse:true,angle:a*180/Math.PI}}const f=(u-.2)/.8,time=t1*(Math.exp(Math.log(6)*f)-1);return{z:1-Math.exp(-time/t1),xy:Math.exp(-time/t2),time,pulse:false,angle:90}}
function vectorArrow(x,y,ex,ey,color,width=3){if(Math.hypot(ex-x,ey-y)<.5)return '';const a=Math.atan2(ey-y,ex-x);return line(x,y,ex,ey,color,width)+V.p(`M${ex-10*Math.cos(a-.4)} ${ey-10*Math.sin(a-.4)}L${ex} ${ey}L${ex-10*Math.cos(a+.4)} ${ey-10*Math.sin(a+.4)}`,'none',color,width)}
function mriProjectionScene(u){const t1=values.T1||1000,t2=values.T2||180,m=mriVectorState(u,t1,t2),ox=205,oy=285,ex=ox+145*m.xy,ey=oy+42*m.xy-175*m.z;let s=panel(20,20,385,470,T('Aimantation des protons','Proton magnetization'))+panel(425,20,455,225,T('Projection longitudinale','Longitudinal projection'))+panel(425,265,455,225,T('Projection transverse','Transverse projection'));
s+=V.p('M115 320L205 285L362 332M205 285V80','none','#93a4b0',1.5)+V.txt(203,70,'z · B₀',16)+V.txt(370,352,'x′',16)+V.txt(102,345,'y′',16)+V.txt(212,445,T('Repère tournant','Rotating frame'),17);
s+=V.p(`M${ox} ${oy}L350 327L260 362L115 320Z`,'#e5f3ed','#bdcfc8',1)+vectorArrow(ox,oy,ox,oy-175*m.z,'#0874b5',4)+vectorArrow(ox,oy,ox+145*m.xy,oy+42*m.xy,'#238665',4)+V.p(`M${ox} ${oy-175*m.z}L${ex} ${ey}L${ox+145*m.xy} ${oy+42*m.xy}`,'none','#94a3ad',1.4)+vectorArrow(ox,oy,ex,ey,'#1e3447',4);
s+=V.txt(165,oy-175*m.z-9,'Mz',16)+V.txt(ox+145*m.xy+10,oy+42*m.xy+25,'Mxy',16)+V.txt(ex+22,ey-12,'M',18)+V.txt(210,392,m.pulse?T('Impulsion RF : ','RF pulse: ')+m.angle.toFixed(0)+'°':'t = '+m.time.toFixed(0)+' ms',17);
for(const [top,which,color,tau] of [[60,'z','#0874b5',t1],[305,'xy','#238665',t2]]){const X=q=>470+350*q/5,Y=v=>top+145-125*v;let pts=Array.from({length:101},(_,i)=>{const q=i*.05;return[X(q),Y(which==='z'?1-Math.exp(-q):Math.exp(-q))]});s+=line(470,top+145,820,top+145,'#8da2af',1)+line(470,top+15,470,top+145,'#8da2af',1)+path(pts,color,2.6)+V.txt(460,top+25,'1',13)+V.txt(460,top+145,'0',13)+V.txt(470,top+164,'0',13)+V.txt(540,top+164,'1',13)+V.txt(820,top+164,'5',13)+V.txt(743,top+181,which==='z'?'t / T₁':'t / T₂',14)+V.txt(650,top+2,which==='z'?'Mz / M₀':'Mxy / M₀',15);if(!m.pulse&&m.time/tau<=5)s+=V.c(X(m.time/tau),Y(which==='z'?m.z:m.xy),5,color)}
s+=V.txt(450,529,T('Après le pulse : Mz récupère avec T₁ ; Mxy décroît avec T₂, simultanément.','After the pulse: Mz recovers with T₁ while Mxy decays with T₂.'),16)+V.txt(450,557,T('Le vecteur décrit l’aimantation collective des protons, pas le spin géant d’une IONP.','The vector represents collective proton magnetization, not an IONP giant spin.'),13);return vsvg(s,900,580)}

function np(x,y,r=25,coated=true){let s=V.c(x,y,r,'url(#vCore)','#243944',1);if(coated)for(let i=0;i<24;i++){const a=i*Math.PI/12,dx=Math.cos(a),dy=Math.sin(a),q=r*.16;s+=V.p(`M${x+dx*r} ${y+dy*r}q${dx*q-dy*q*.5} ${dy*q+dx*q*.5} ${dx*q*1.5} ${dy*q*1.5}t${dx*q} ${dy*q}`,'none','#688a96',1.1);}return s;}
function applicationLinks(id){const links={mri:['https://www.ferabright.com/','Azurity · Ferabright',T('IRM : produit à base de ferumoxytol. Consulter les indications américaines du fabricant.','MRI: ferumoxytol product. See the manufacturer’s US indications.')],mpi:['https://www.magneticinsight.com/','Magnetic Insight',T('Instrumentation MPI pour la recherche.','MPI research instrumentation.')],heat:['https://www.nanothermtx.com/','Nanotherm Therapeutics',T('Hyperthermie magnétique : dispositif expérimental.','Magnetic hyperthermia: investigational device.')]};if(!links[id])return '';const [url,name,note]=links[id];return `<h3>${T('Du principe à l’application','From principle to application')}</h3><p><a href="${url}" target="_blank" rel="noopener noreferrer">${name}</a> · ${note}</p>`;}
